# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`event-pipeline.md`](event-pipeline.md) for the pipeline delivery plan.

//! Integration tests for the public crate surface.
//!
//! These tests link against the crate as a downstream consumer would: they can
//! only use what `src/lib.rs` re-exports, plus the storage crate a host already
//! has. A change that breaks a test here is a breaking change for users.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::sync::Arc;

use tinyeventqueues::config::{SHIPPED_PIPELINE_JSON, parse_pipeline_config, shipped_manifest};
use tinyeventqueues::{
    CollectingSink, Disposition, Error, EventKind, InboundEvent, ManualClock, Pipeline, Reason,
    Sender, tinyeventqueues_bus,
};
use tinystoragedrivers_core::queue::DocumentQueue;
use tinystoragedrivers_core::{MemoryStorage, Scope, StorageBackend};

fn event(id: &str) -> InboundEvent {
    InboundEvent::new(
        "webhook:github",
        id,
        "repo-1",
        Sender::new("octocat"),
        EventKind::Trigger,
        0,
    )
}

#[tokio::test]
async fn a_restarted_pipeline_rejects_a_redelivery() {
    let clock = ManualClock::new(5_000);
    let storage = MemoryStorage::with_clock(clock.clock())
        .for_scope(&Scope::local())
        .unwrap();
    let docs = Arc::clone(storage.documents());
    let build = || async {
        let queues = Arc::new(DocumentQueue::new(&docs).with_clock(clock.clock()));
        Pipeline::builder(queues, Arc::clone(&docs))
            .clock(clock.clock())
            .build()
            .await
            .unwrap()
    };

    let sink = Arc::new(CollectingSink::new());
    let first = Pipeline::builder(
        Arc::new(DocumentQueue::new(&docs).with_clock(clock.clock())),
        Arc::clone(&docs),
    )
    .clock(clock.clock())
    .sink(sink.clone())
    .build()
    .await
    .unwrap();
    let accepted = first.ingest(vec![event("delivery-1")]).await.unwrap();
    assert_eq!(accepted.results[0].disposition, Disposition::Accepted);
    assert_eq!(sink.outcomes()[0].reason, Reason::Ingested);

    let restarted = build().await;
    let again = restarted.ingest(vec![event("delivery-1")]).await.unwrap();
    assert_eq!(again.results[0].disposition, Disposition::Duplicate);
    assert_eq!(again.results[0].reason, Some(Reason::DuplicateRedelivery));
}

#[test]
fn the_shipped_files_are_public_and_valid() {
    assert_ne!(shipped_manifest().unwrap().queues.len(), 0);
    let config = parse_pipeline_config(SHIPPED_PIPELINE_JSON).unwrap();
    assert_eq!(config.version, 1);
}

#[test]
fn config_errors_are_matchable() {
    let error = parse_pipeline_config("{\"version\": 1}").unwrap_err();
    assert!(matches!(error, Error::Config { .. }));
}

#[test]
fn the_contract_is_reexported_as_the_same_types() {
    let event: tinyeventqueues_bus::InboundEvent = event("1");
    let _: InboundEvent = event;
    assert!(tinyeventqueues::is_compatible(
        tinyeventqueues::CONTRACT_VERSION
    ));
}

/// A host as a downstream crate writes one.
#[derive(Debug, Default)]
struct Agent {
    turns: std::sync::Mutex<Vec<tinyeventqueues::Turn>>,
}

#[async_trait::async_trait]
impl tinyeventqueues::Host for Agent {
    async fn classify_salience(
        &self,
        _request: tinyeventqueues::ClassifySalienceRequest,
    ) -> tinyeventqueues::Result<tinyeventqueues::ClassifySalienceResponse> {
        Ok(tinyeventqueues::ClassifySalienceResponse::new(
            tinyeventqueues::SalienceClass::Fyi,
        ))
    }

    async fn deliver(
        &self,
        request: tinyeventqueues::DeliverRequest,
    ) -> tinyeventqueues::Result<tinyeventqueues::DeliverResponse> {
        self.turns.lock().unwrap().push(request.turn);
        Ok(tinyeventqueues::DeliverResponse::new(
            tinyeventqueues::DeliverStatus::Accepted,
        ))
    }
}

#[tokio::test]
async fn a_host_receives_turns_from_drain() {
    let clock = ManualClock::new(5_000);
    let storage = MemoryStorage::with_clock(clock.clock())
        .for_scope(&Scope::local())
        .unwrap();
    let docs = Arc::clone(storage.documents());
    let agent = Arc::new(Agent::default());
    let pipeline = Pipeline::builder(
        Arc::new(DocumentQueue::new(&docs).with_clock(clock.clock())),
        Arc::clone(&docs),
    )
    .clock(clock.clock())
    .host(agent.clone())
    .build()
    .await
    .unwrap();
    let dm = InboundEvent::new(
        "web:chat",
        "1",
        "visitor-1",
        Sender::new("v"),
        EventKind::Message,
        5_000,
    )
    .direct(true)
    .text("hi there");
    pipeline.ingest(vec![dm]).await.unwrap();
    pipeline.drain().await.unwrap();
    clock.advance(2_000);
    let report = pipeline.drain().await.unwrap();
    assert_eq!(report.dispatched, 1);
    assert_eq!(agent.turns.lock().unwrap()[0].events[0].event_id, "1");
    assert_eq!(pipeline.stats().await.unwrap().outcomes.delivered, 1);
}

//! Shared fixtures for the unit tests: storage, a queue backend without
//! dedupe, and events.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::sync::Arc;

use async_trait::async_trait;
use tinyeventqueues_bus::{EventKind, InboundEvent, Sender};
use tinystoragedrivers_core::queue::{
    DeadLetter, Delivery, DocumentQueue, Enqueued, NewMessage, QueueFeatures, QueueSpec,
    QueueStats, QueueStore, Receipt, Retry,
};
use tinystoragedrivers_core::{
    DocumentStore, MemoryStorage, Result, Scope, StorageBackend, StorageError,
};

use crate::{ManualClock, Pipeline, PipelineBuilder};

/// One storage backend, shared by every pipeline built over it, so a new
/// pipeline is a restart.
pub(crate) struct Fixture {
    pub(crate) clock: ManualClock,
    pub(crate) docs: Arc<dyn DocumentStore>,
    pub(crate) queues: Arc<dyn QueueStore>,
}

impl Fixture {
    /// A queue backend with every feature (`DocumentQueue`).
    pub(crate) fn new() -> Self {
        Self::with_native(true)
    }

    /// With `native`, a `DocumentQueue`; without, a [`Broker`] that has
    /// neither dedupe nor groups and refuses messages that use them, the way
    /// the `RabbitMQ` driver does.
    pub(crate) fn with_native(native: bool) -> Self {
        let clock = ManualClock::new(START_MS);
        let storage = MemoryStorage::with_clock(clock.clock())
            .for_scope(&Scope::local())
            .unwrap();
        let docs = Arc::clone(storage.documents());
        let queue = DocumentQueue::new(&docs).with_clock(clock.clock());
        let queues: Arc<dyn QueueStore> = if native {
            Arc::new(queue)
        } else {
            Arc::new(Broker(queue))
        };
        Self {
            clock,
            docs,
            queues,
        }
    }

    pub(crate) fn builder(&self) -> PipelineBuilder {
        Pipeline::builder(Arc::clone(&self.queues), Arc::clone(&self.docs))
            .clock(self.clock.clock())
    }

    /// A pipeline with the shipped files: building one again is a restart.
    pub(crate) async fn pipeline(&self) -> Pipeline {
        self.builder().build().await.unwrap()
    }
}

/// Where every [`Fixture`] clock starts.
pub(crate) const START_MS: u64 = 1_000_000;

/// An event from a human in a group conversation, received at [`START_MS`].
pub(crate) fn event(source: &str, id: &str, conversation: &str) -> InboundEvent {
    InboundEvent::new(
        source,
        id,
        conversation,
        Sender::new("user-1"),
        EventKind::Message,
        START_MS,
    )
    .text(format!("message {id} {}", words(id)))
}

/// A queue backend like the `RabbitMQ` driver: no dedupe and no groups, and
/// a message that sets `group` or `dedupe_key` is refused.
#[derive(Debug)]
pub(crate) struct Broker(pub(crate) DocumentQueue);

#[async_trait]
impl QueueStore for Broker {
    fn features(&self) -> QueueFeatures {
        QueueFeatures {
            dedupe: false,
            groups: false,
            ..self.0.features()
        }
    }
    async fn ensure_queue(&self, queue: &str, spec: &QueueSpec) -> Result<()> {
        self.0.ensure_queue(queue, spec).await
    }
    async fn enqueue(&self, queue: &str, messages: &[NewMessage]) -> Result<Vec<Enqueued>> {
        if messages
            .iter()
            .any(|message| message.group.is_some() || message.dedupe_key.is_some())
        {
            return Err(StorageError::invalid_input(
                "this queue backend supports neither groups nor dedupe keys",
            ));
        }
        self.0.enqueue(queue, messages).await
    }
    async fn receive(
        &self,
        queue: &str,
        max: u32,
        visibility_ms: u64,
        consumer: &str,
    ) -> Result<Vec<Delivery>> {
        self.0.receive(queue, max, visibility_ms, consumer).await
    }
    async fn ack(&self, queue: &str, receipt: &Receipt) -> Result<bool> {
        self.0.ack(queue, receipt).await
    }
    async fn nack(&self, queue: &str, receipt: &Receipt, retry: Retry) -> Result<bool> {
        self.0.nack(queue, receipt, retry).await
    }
    async fn extend(&self, queue: &str, receipt: &Receipt, visibility_ms: u64) -> Result<bool> {
        self.0.extend(queue, receipt, visibility_ms).await
    }
    async fn stats(&self, queue: &str) -> Result<QueueStats> {
        self.0.stats(queue).await
    }
    async fn dead_letters(&self, queue: &str, limit: usize) -> Result<Vec<DeadLetter>> {
        self.0.dead_letters(queue, limit).await
    }
    async fn redrive(&self, queue: &str, id: &str) -> Result<bool> {
        self.0.redrive(queue, id).await
    }
    async fn purge(&self, queue: &str) -> Result<u64> {
        self.0.purge(queue).await
    }
}

/// Take every turn waiting on `lane`, in delivery order, acknowledging each
/// so the next of its conversation becomes deliverable.
pub(crate) async fn take_turns(
    fixture: &Fixture,
    pipeline: &Pipeline,
    lane: tinyeventqueues_bus::Lane,
) -> Vec<crate::turn::PendingTurn> {
    let queue = pipeline.queues().lane(lane).name.clone();
    let mut turns = Vec::new();
    loop {
        let batch = fixture
            .queues
            .receive(&queue, 100, 60_000, "inspect")
            .await
            .unwrap();
        if batch.is_empty() {
            return turns;
        }
        for delivery in batch {
            turns.push(serde_json::from_value(delivery.payload).unwrap());
            fixture.queues.ack(&queue, &delivery.receipt).await.unwrap();
        }
    }
}

/// A few words derived from `id`, so test events' texts are not
/// near-duplicates of each other (which would habituate their scores).
fn words(id: &str) -> String {
    const WORDS: [&str; 16] = [
        "amber", "birch", "cobalt", "delta", "ember", "fjord", "garnet", "harbor", "iris",
        "juniper", "kelp", "lumen", "maple", "nectar", "onyx", "prism",
    ];
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in id.bytes() {
        hash = (hash ^ u64::from(byte)).wrapping_mul(0x0100_0000_01b3);
    }
    (0..6)
        .map(|_| {
            hash = hash
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            WORDS[usize::try_from(hash >> 60).unwrap()]
        })
        .collect::<Vec<_>>()
        .join(" ")
}

/// How a [`ScriptedHost`] answers a turn.
type Decide = dyn Fn(&tinyeventqueues_bus::Turn) -> crate::Result<tinyeventqueues_bus::DeliverStatus>
    + Send
    + Sync;

/// A host whose verdict on each turn is scripted, and which records every
/// turn it is handed.
pub(crate) struct ScriptedHost {
    decide: Box<Decide>,
    pub(crate) delivered: std::sync::Mutex<Vec<tinyeventqueues_bus::Turn>>,
}

impl std::fmt::Debug for ScriptedHost {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ScriptedHost").finish_non_exhaustive()
    }
}

impl ScriptedHost {
    pub(crate) fn new(
        decide: impl Fn(&tinyeventqueues_bus::Turn) -> crate::Result<tinyeventqueues_bus::DeliverStatus>
        + Send
        + Sync
        + 'static,
    ) -> Arc<Self> {
        Arc::new(Self {
            decide: Box::new(decide),
            delivered: std::sync::Mutex::new(Vec::new()),
        })
    }

    /// A host that accepts everything.
    pub(crate) fn accepting() -> Arc<Self> {
        Self::new(|_| Ok(tinyeventqueues_bus::DeliverStatus::Accepted))
    }

    pub(crate) fn turns(&self) -> Vec<tinyeventqueues_bus::Turn> {
        self.delivered.lock().unwrap().clone()
    }
}

#[async_trait]
impl crate::Host for ScriptedHost {
    async fn classify_salience(
        &self,
        _request: tinyeventqueues_bus::ClassifySalienceRequest,
    ) -> crate::Result<tinyeventqueues_bus::ClassifySalienceResponse> {
        Ok(tinyeventqueues_bus::ClassifySalienceResponse::new(
            tinyeventqueues_bus::SalienceClass::Fyi,
        ))
    }

    async fn deliver(
        &self,
        request: tinyeventqueues_bus::DeliverRequest,
    ) -> crate::Result<tinyeventqueues_bus::DeliverResponse> {
        self.delivered.lock().unwrap().push(request.turn.clone());
        (self.decide)(&request.turn).map(tinyeventqueues_bus::DeliverResponse::new)
    }
}

//! Tests for the module's storage declaration.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::*;
use tinystoragedrivers_core::schema::{Item, Registry};

#[test]
fn every_collection_is_module_scoped_under_the_owner() {
    let schema = storage_schema();
    assert_eq!(schema.owner.as_str(), OWNER);
    assert_eq!(schema.items.len(), collection_specs().len());
    for item in &schema.items {
        assert_eq!(item.scope(), ScopeClass::Module);
        assert!(item.name().starts_with("teq."), "{}", item.name());
    }
}

#[test]
fn declared_specs_are_the_specs_the_module_ensures() {
    let declared: Vec<CollectionSpec> = storage_schema()
        .items
        .into_iter()
        .filter_map(|item| match item {
            Item::Collection { spec, version, .. } => {
                assert_eq!(version, COLLECTION_VERSION);
                Some(spec)
            }
            _ => None,
        })
        .collect();
    assert_eq!(declared, collection_specs());
}

#[test]
fn the_schema_composes_alone() {
    let registry = Registry::compose(vec![storage_schema()]);
    assert!(registry.is_ok(), "{:?}", registry.err());
}

#[test]
fn shipped_files_are_json_documents() {
    for text in [SHIPPED_QUEUES_JSON, SHIPPED_PIPELINE_JSON] {
        let value: serde_json::Value = serde_json::from_str(text).unwrap();
        assert_eq!(value["version"], 1);
    }
}

//! Tests for opening the module's storage: the host's over the bus, and the
//! memory fallback.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyeventqueues_bus::storage::OUTCOMES;
use tinystoragedrivers_core::{Precondition, Scope, StorageBackend};

use super::*;
use crate::tinybus_module::tests::rig;
use tinybus::{Connection, broker::Broker, transport::memory::MemoryBus};

#[path = "storage_bound_tests.rs"]
mod bound_tests;

#[tokio::test]
async fn a_host_that_serves_storage_backs_the_pipeline() {
    let rig = rig(true).await;
    let module = Connection::connect(rig.bus.connect().await.unwrap())
        .await
        .unwrap();
    let backing = open(module, None).await.unwrap();
    assert!(backing.durable);
    assert!(format!("{backing:?}").contains("durable: true"));

    // A write through the module lands in the host's backend.
    for spec in tinyeventqueues_bus::storage::collection_specs() {
        backing.docs.ensure_collection(&spec).await.unwrap();
    }
    backing
        .docs
        .put(OUTCOMES, "x", serde_json::json!({}), Precondition::None)
        .await
        .unwrap();
    let host = rig.backend.for_scope(&Scope::local()).unwrap();
    assert!(host.documents().get(OUTCOMES, "x").await.unwrap().is_some());
}

#[tokio::test]
async fn a_host_without_storage_leaves_the_pipeline_on_memory() {
    let rig = rig(false).await;
    let module = Connection::connect(rig.bus.connect().await.unwrap())
        .await
        .unwrap();
    let backing = open(module, None).await.unwrap();
    assert!(!backing.durable);
}

#[tokio::test]
async fn a_storage_host_that_cannot_be_reached_fails_setup_instead_of_using_memory() {
    let rig = rig(false).await;
    // Something owns the storage name but serves no storage objects: a host
    // whose storage is present but failing.
    rig.host
        .request_name(tinystoragedrivers_busproxy::HOST_NAME)
        .await
        .unwrap();
    let module = Connection::connect(rig.bus.connect().await.unwrap())
        .await
        .unwrap();
    let refused = open(module, None).await;
    assert!(refused.is_err(), "fell back to memory: {refused:?}");
}

#[tokio::test]
async fn an_explicit_bound_descriptor_never_falls_back_when_its_route_is_unavailable() {
    let bus = MemoryBus::new();
    Broker::new().spawn(bus.clone());
    let module = Connection::connect(bus.connect().await.unwrap())
        .await
        .unwrap();
    assert!(
        module
            .name_owner(tinystoragedrivers_busproxy::HOST_NAME)
            .await
            .unwrap()
            .is_none(),
        "the fixture has no legacy well-known storage root"
    );
    let descriptor = serde_json::from_value(serde_json::json!({
        "service_peer": ":1.404",
        "registration_id": 404,
        "object_root": "/ai/tinyhumans/tinystorage/Leases/404",
    }))
    .unwrap();

    let refused = open(module, Some(descriptor)).await;
    assert!(
        refused.is_err(),
        "an explicit but unavailable lease must fail instead of using memory: {refused:?}"
    );
}

//! Exercise the module's explicit TSD lease route through a governed host.

use std::sync::Arc;
use std::time::Duration;

use async_trait::async_trait;
use tinybus::{
    Connection,
    broker::Broker,
    module::ModuleHost,
    transport::memory::{MemoryBus, MemoryTransport},
};
use tinyeventqueues_bus::{
    Disposition, EventKind, InboundEvent, IngestRequest, IngestResponse, Sender, names,
};
use tinystoragedrivers_bus::StorageNeeds;
use tinystoragedrivers_busproxy::{
    AuditEvent, AuditSink, Environment, GovernedEndpointLimits, GovernedStorage, GrantPolicy,
    HostContext, HostFailure, ResolvedStorage, StorageDescriptor, StorageGrant, StorageLease,
};
use tinystoragedrivers_client::StorageServer;
use tinystoragedrivers_core::{MemoryStorage, Scope, StorageBackend};
use tinystoragedrivers_tinybus::{StorageRegistration, attach_storage};

use crate::config::shipped_manifest;
use crate::tinybus_module::{setup, storage, ticker::Slot};

struct QueueHostContext;

impl HostContext for QueueHostContext {}

struct QueueHostEnvironment {
    backend: Arc<MemoryStorage>,
    scope: Scope,
    manifest: Arc<tinystoragedrivers_core::queue::QueueManifest>,
}

#[async_trait]
impl Environment<QueueHostContext> for QueueHostEnvironment {
    async fn resolve(
        &self,
        _context: &QueueHostContext,
        _module: &tinybus::module::ModuleId,
    ) -> std::result::Result<ResolvedStorage, HostFailure> {
        let storage = self
            .backend
            .for_scope(&self.scope)
            .map_err(|_| HostFailure::Denied("test-storage-unavailable"))?;
        let collections: Vec<tinystoragedrivers_bus::CollectionSpec> = serde_json::from_value(
            serde_json::to_value(tinyeventqueues_bus::storage::collection_specs())
                .map_err(|_| HostFailure::Denied("event-queue-schema-serialization-failed"))?,
        )
        .map_err(|_| HostFailure::Denied("event-queue-schema-decode-failed"))?;
        let grant = StorageGrant::from_needs(
            StorageNeeds {
                collections: &collections,
                ..StorageNeeds::default()
            },
            &GrantPolicy {
                writable: true,
                ..GrantPolicy::default()
            },
        )
        .map_err(|_| HostFailure::Denied("event-queue-storage-grant-invalid"))?;
        let grant = grant
            .with_queue_manifest(Arc::clone(&self.manifest))
            .map_err(|_| HostFailure::Denied("event-queue-manifest-invalid"))?;
        let server = StorageServer::new(storage).with_queue_manifest(Arc::clone(&self.manifest));
        Ok(ResolvedStorage {
            backend_identity: "event-queues-bound-test".to_owned(),
            binding_epoch: 1,
            canonical_scope: "bound-queue-tenant".to_owned(),
            grant,
            server: Arc::new(server),
        })
    }

    async fn admit_write(
        &self,
        _context: &QueueHostContext,
        _module: &tinybus::module::ModuleId,
    ) -> std::result::Result<(), HostFailure> {
        Ok(())
    }
}

struct QueueHostAudit;

impl AuditSink for QueueHostAudit {
    fn record(&self, _event: AuditEvent) {}
}

type QueueHostRegistration =
    StorageRegistration<QueueHostEnvironment, QueueHostAudit, QueueHostContext>;

struct SetupFixture {
    registration: Arc<QueueHostRegistration>,
}

static SETUP_FIXTURE: std::sync::OnceLock<std::sync::Mutex<Option<SetupFixture>>> =
    std::sync::OnceLock::new();

fn setup_fixture() -> &'static std::sync::Mutex<Option<SetupFixture>> {
    SETUP_FIXTURE.get_or_init(|| std::sync::Mutex::new(None))
}

type ObservedLease = (StorageLease, StorageDescriptor, Connection);

static OBSERVED_LEASE: std::sync::OnceLock<std::sync::Mutex<Option<ObservedLease>>> =
    std::sync::OnceLock::new();

fn observed_lease() -> &'static std::sync::Mutex<Option<ObservedLease>> {
    OBSERVED_LEASE.get_or_init(|| std::sync::Mutex::new(None))
}

mod bound_module_export {
    use super::*;

    async fn setup_with_context(
        context: tinybus_module::ModuleSetupContext,
        _config: Option<serde_json::Value>,
    ) -> tinybus::Result<()> {
        let fixture = setup_fixture()
            .lock()
            .map_err(|_| tinybus::Error::failed("bound storage fixture lock poisoned"))?
            .take()
            .ok_or_else(|| tinybus::Error::failed("bound storage fixture missing"))?;
        let connection = context.connection().clone();
        let peer = connection
            .unique_name()
            .ok_or_else(|| tinybus::Error::failed("event-queues module has no unique peer"))?;
        let (lease, descriptor) = fixture
            .registration
            .register_lease(
                tinystoragedrivers_busproxy::HostStorageContext::new(QueueHostContext),
                peer,
            )
            .await
            .map_err(|_| tinybus::Error::failed("event-queues storage lease was refused"))?;
        *observed_lease()
            .lock()
            .map_err(|_| tinybus::Error::failed("bound storage lease lock poisoned"))? =
            Some((lease, descriptor.clone(), connection.clone()));

        let mut config = serde_json::json!({ "timer": { "enabled": false } });
        config["storage_descriptor"] = serde_json::to_value(descriptor)
            .map_err(|_| tinybus::Error::failed("storage descriptor serialization failed"))?;
        setup(connection, config, Slot::default()).await
    }

    tinybus_module::module_export_static! {
        setup_with_context = setup_with_context,
        config = Option<serde_json::Value>,
        worker_threads = 2,
        provides = ["ai.tinyhumans.tinyeventqueues.EventQueues"],
        methods = ["Ingest", "Configure", "Stats", "ListDead", "Redrive", "Drain"],
        signals = [],
        requires = [],
        optional = [],
        lazy = false,
    }
}

#[tokio::test(flavor = "multi_thread")]
async fn a_host_issued_lease_supplies_scoped_queues_and_rejects_other_callers()
-> std::result::Result<(), Box<dyn std::error::Error>> {
    let bus = MemoryBus::new();
    let broker = Broker::new_restricted_module_control();
    let (broker_transport, controller_transport) = MemoryTransport::pair();
    broker.attach_module_controller(Arc::new(broker_transport))?;
    let controller = Connection::connect(Box::new(controller_transport)).await?;
    let broker_task = broker.spawn(bus.clone());
    let host = ModuleHost::new(broker);
    let backend = Arc::new(MemoryStorage::new());
    let scope = Scope::new("bound-queue-tenant")?;
    let manifest = Arc::new(shipped_manifest()?);
    let registration: Arc<QueueHostRegistration> = Arc::new(
        attach_storage(
            &host,
            &controller,
            GovernedStorage::new(
                Arc::new(QueueHostEnvironment {
                    backend: Arc::clone(&backend),
                    scope: scope.clone(),
                    manifest,
                }),
                Arc::new(QueueHostAudit),
                GovernedEndpointLimits::default(),
            ),
            tokio::runtime::Handle::current(),
        )
        .await
        .map_err(|_| std::io::Error::other("governed storage attachment failed"))?,
    );
    *setup_fixture()
        .lock()
        .map_err(|_| std::io::Error::other("bound storage fixture lock poisoned"))? =
        Some(SetupFixture {
            registration: Arc::clone(&registration),
        });

    let info = host
        .attach_linked_with_config(bound_module_export::linked_module()?, serde_json::json!({}))?;
    if let Err(error) = host.ensure_ready(info.manifest.bus_name.as_str()).await {
        return Err(
            std::io::Error::other(format!("bound event-queues setup failed: {error}")).into(),
        );
    }
    let (lease, descriptor, module_connection) = observed_lease()
        .lock()
        .map_err(|_| std::io::Error::other("bound storage lease lock poisoned"))?
        .take()
        .ok_or_else(|| std::io::Error::other("bound storage lease was not captured"))?;

    let client = Connection::connect(bus.connect().await?).await?;
    let proxy = client.proxy(names::INTERFACE, names::OBJECT_PATH, names::INTERFACE)?;
    let event = InboundEvent::new(
        "web:chat",
        "bound-1",
        "conversation",
        Sender::new("user"),
        EventKind::Message,
        1,
    );
    let response: IngestResponse = proxy
        .call(names::methods::INGEST, (IngestRequest::new(vec![event]),))
        .await?;
    assert_eq!(response.results[0].disposition, Disposition::Accepted);

    let scoped = backend.for_scope(&scope)?;
    assert_eq!(scoped.queues().stats("teq.ingress").await?.ready, 1);

    let wrong_peer = storage::open(client.clone(), Some(descriptor.clone())).await;
    assert!(
        wrong_peer.is_err(),
        "a different bus peer must not use the module's lease: {wrong_peer:?}"
    );

    assert!(registration.revoke(&lease).await);
    let revoked = storage::open(module_connection, Some(descriptor)).await;
    assert!(
        revoked.is_err(),
        "a revoked lease must fail rather than falling back to memory: {revoked:?}"
    );

    let registration = Arc::try_unwrap(registration)
        .map_err(|_| std::io::Error::other("storage registration remained in use"))?;
    registration.shutdown().await?;
    host.shutdown(Duration::from_secs(2)).await;
    broker_task.abort();
    Ok(())
}

