//! Unit tests for the contract version and its bind rule.

use super::{CONTRACT_VERSION, binds, is_compatible};

#[test]
fn the_shipped_contract_version_is_pinned() {
    assert_eq!(CONTRACT_VERSION, (0, 2));
}

#[test]
fn the_contract_binds_to_itself() {
    assert!(is_compatible(CONTRACT_VERSION));
}

#[test]
fn a_newer_minor_on_the_module_side_binds() {
    assert!(is_compatible((0, 2)));
    assert!(is_compatible((0, 97)));
}

#[test]
fn an_older_minor_on_the_module_side_is_rejected() {
    assert!(!binds((1, 4), (1, 2)));
    assert!(binds((1, 4), (1, 4)));
}

#[test]
fn a_different_major_is_rejected() {
    assert!(!is_compatible((1, 1)));
    assert!(!is_compatible((2, 97)));
}

//! Unit tests for the clocks.

use super::*;

#[test]
fn a_manual_clock_moves_only_when_told() {
    let clock = ManualClock::new(10);
    let read = clock.clock();
    assert_eq!(read(), 10);
    clock.advance(5);
    assert_eq!(clock.now(), 15);
    clock.set(3);
    assert_eq!(read(), 3);
}

#[test]
fn the_system_clock_reads_a_plausible_time() {
    // 2020-01-01 in epoch milliseconds.
    assert!(system_clock()() > 1_577_836_800_000);
}

//! Unit tests for the outcome sinks.

use tinyeventqueues_bus::{Disposition, EventRef, Outcome, Reason};

use super::*;

#[test]
fn the_collecting_sink_keeps_outcomes_in_order() {
    let sink = CollectingSink::new();
    let first = Outcome::new(
        EventRef::new("s", "1"),
        Disposition::Accepted,
        Reason::Ingested,
        1,
    );
    let second = Outcome::new(
        EventRef::new("s", "2"),
        Disposition::Dropped,
        Reason::BotLoop,
        2,
    );
    sink.observe(&first);
    NoopSink.observe(&first);
    sink.observe(&second);
    assert_eq!(sink.outcomes(), vec![first, second]);
}

//! Unit tests for the bus name table.

use super::{INTERFACE, METHODS, OBJECT_PATH, host, methods};

fn path_form(interface: &str) -> String {
    format!("/{}", interface.replace('.', "/"))
}

#[test]
fn the_object_paths_are_the_interfaces_in_path_form() {
    assert_eq!(OBJECT_PATH, path_form(INTERFACE));
    assert_eq!(host::OBJECT_PATH, path_form(host::INTERFACE));
}

#[test]
fn every_member_is_listed_exactly_once() {
    for table in [METHODS, host::METHODS] {
        let mut sorted = table.to_vec();
        sorted.sort_unstable();
        let mut deduplicated = sorted.clone();
        deduplicated.dedup();
        assert_eq!(sorted, deduplicated);
    }
}

#[test]
fn the_method_tables_hold_the_declared_members() {
    assert_eq!(
        METHODS,
        [
            methods::INGEST,
            methods::CONFIGURE,
            methods::STATS,
            methods::LIST_DEAD,
            methods::REDRIVE,
            methods::DRAIN,
        ]
    );
    assert_eq!(
        host::METHODS,
        [host::methods::CLASSIFY_SALIENCE, host::methods::DELIVER]
    );
}

#[test]
fn no_member_name_is_empty() {
    assert!(METHODS.iter().chain(host::METHODS).all(|m| !m.is_empty()));
}
